import math, random, time

def acf(x, kmax):
    n=len(x); m=sum(x)/n; d=[v-m for v in x]
    c0=sum(v*v for v in d)/n
    return [ (sum(d[i]*d[i+k] for i in range(n-k))/n)/c0 for k in range(1,kmax+1) ]

def local_maxima(r):
    return [k for k in range(1,len(r)-1) if r[k]>=r[k-1] and r[k]>r[k+1]]

def prominence(r,k):
    left=min(r[0:k+1]) if k>0 else r[k]
    j=k+1; right=r[k]
    # walk to the first local min on each side (approximation of prominence)
    while j<len(r)-1 and r[j]>=r[j+1]: j+=1
    right=r[min(j,len(r)-1)]
    return r[k]-max(left,right)

def harmonized(r, k):  # k is 1-indexed lag -> index k-1
    # a candidate is a HARMONIC of a shorter lag if some divisor lag has >= ACF
    divs=[k//d for d in (2,3,4) if k%d==0 and k//d>=2]
    if not divs: return r[k-1], False
    best=max(r[d-1] for d in divs)
    return r[k-1]-best, (r[k-1] <= 1.02*best)

def recommend(r, band, kmax):
    scored=[]
    for k in local_maxima(r):
        lag=k+1
        if lag<2 or r[k]<=band[k]: continue
        prom=prominence(r,k)
        harm_pen, is_harm = harmonized(r,lag)
        if is_harm: continue
        scored.append((prom, lag, r[k], round(harm_pen,3)))
    scored.sort(reverse=True)
    return scored

# ---- detrending: centered moving average (2P+1 approx via window W) ----
def ma_detrend(x,W):
    n=len(x); out=[]
    for i in range(n):
        a=max(0,i-W); b=min(n,i+W+1)
        out.append(x[i]-sum(x[a:b])/(b-a))
    return out

def trend_test(x):  # simple: OLS slope z-score vs residual sd
    n=len(x); mx=sum(range(n))/n; my=sum(x)/n
    sxy=sum((i-mx)*(x[i]-my) for i in range(n)); sxx=sum((i-mx)**2 for i in range(n))
    b=sxy/sxx; a=my-b*mx
    res=[x[i]-(a+b*i) for i in range(n)]; sr=math.sqrt(sum(e*e for e in res)/max(1,n-2))
    se=sr/math.sqrt(sxx)
    return b/se

def fft_c(z):
    n=len(z)
    if n<=1: return z
    even=fft_c(z[0::2]); odd=fft_c(z[1::2]); out=[0j]*n
    for k in range(n//2):
        ang=-2*math.pi*k/n; w=complex(math.cos(ang),math.sin(ang))
        t=w*odd[k]
        out[k]=even[k]+t; out[k+n//2]=even[k]-t
    return out

def spectrum_period(x):
    n=len(x); N=1
    while N<2*n: N<<=1
    m=sum(x)/n
    A=fft_c([(v-m)+0j for v in x]+[0j]*(N-n))
    pw=[abs(z)**2 for z in A[:N//2]]
    k=max(range(1,len(pw)), key=lambda i:pw[i])
    # parabolic refinement on log-power
    y0,y1,y2=math.log(pw[k-1]),math.log(pw[k]),math.log(pw[k+1])
    d=0.5*(y0-y2)/(y0-2*y1+y2)
    kref=k+d
    return N/kref, kref

def make(P,n,trend,noise,sec=None,seed=0,harm=0.0,rnd_amp=0.0):
    rnd=random.Random(seed)
    out=[]
    for i in range(n):
        v=math.sin(2*math.pi*i/P)+harm*math.sin(2*math.pi*2*i/P)
        if sec: v+=sec*math.sin(2*math.pi*i/sec)
        v+=trend*(i/n)+noise*rnd.gauss(0,1)
