import math, random, time
def acf(x, kmax):
    n=len(x); m=sum(x)/n; d=[v-m for v in x]; c0=sum(v*v for v in d)/n
    return [(sum(d[i]*d[i+k] for i in range(n-k))/n)/c0 for k in range(1,kmax+1)]
def maxima(r): return [k for k in range(1,len(r)-1) if r[k]>=r[k-1] and r[k]>r[k+1]]
def prom(r,k):
    left=min(r[0:k+1]); j=k+1
    while j<len(r)-1 and r[j]>=r[j+1]: j+=1
    return r[k]-max(left, r[min(j,len(r)-1)])
def harmonic(r,k):
    divs=[k//d for d in (2,3,4) if k%d==0 and k//d>=2]
    if not divs: return False
    return r[k-1] <= 1.02*max(r[d-1] for d in divs)
def ma_detrend(x,W):
    n=len(x)
    return [x[i]-sum(x[max(0,i-W):min(n,i+W+1)])/len(x[max(0,i-W):min(n,i+W+1)]) for i in range(n)]
def trendz(x):
    n=len(x); mx=(n-1)/2; my=sum(x)/n
    sxy=sum((i-mx)*(x[i]-my) for i in range(n)); sxx=sum((i-mx)**2 for i in range(n))
    b=sxy/sxx; res=[x[i]-(my-b*mx)-b*i for i in range(n)]
    sr=math.sqrt(sum(e*e for e in res)/max(1,n-2)); return b/(sr/math.sqrt(sxx))
def fft_c(z):
    n=len(z)
    if n<=1: return z
    e=fft_c(z[0::2]); o=fft_c(z[1::2]); out=[0j]*n
    for k in range(n//2):
        a=-2*math.pi*k/n; t=complex(math.cos(a),math.sin(a))*o[k]
        out[k]=e[k]+t; out[k+n//2]=e[k]-t
    return out
def spec(x):
    n=len(x); N=1
    while N<2*n: N<<=1
    m=sum(x)/n; A=fft_c([(v-m)+0j for v in x]+[0j]*(N-n))
    pw=[abs(z)**2 for z in A[:N//2]]
    k=max(range(1,len(pw)-1), key=lambda i:pw[i])
    y0,y1,y2=math.log(pw[k-1]),math.log(pw[k]),math.log(pw[k+1])
    d=0.5*(y0-y2)/(y0-2*y1+y2) if (y0-2*y1+y2)!=0 else 0.0
    return N/(k+d)
def make(P,n,trend,noise,sec=0.0,seed=0,harm=0.0):
    rnd=random.Random(seed); out=[]
    for i in range(n):
        v=math.sin(2*math.pi*i/P)+harm*math.sin(4*math.pi*i/P)
        if sec: v+=sec*math.sin(2*math.pi*i/168)
        out.append(v+trend*(i/n)+noise*rnd.gauss(0,1))
    return out
def run(label,x,kmax=400,W=49,force=None):
    n=len(x); km=min(kmax,max(2,n//3)); tt=trendz(x)
    use = (ma_detrend(x,W) if abs(tt)>3 else x) if force is None else force
    r=acf(use,km); s=0.0; band=[]
    for v in r: s+=2*v*v; band.append(1.96*math.sqrt((1+2*s)/n))
    sc=[(prom(r,k),k+1) for k in maxima(r) if r[k]>band[k] and not harmonic(r,k+1)]
    sc.sort(reverse=True)
    top=[l for _,l in sc[:3]]
    print(f"{label:<32} trendz={tt:7.1f} detrend={'Y' if (force=='ma' or (force is None and abs(tt)>3)) else 'N'} top={str(top):<18} fftP={spec(use):7.2f}")
print("== representation switch check ==")
run("P=24 clean", make(24,1440,0.0,0.1))
run("P=24 + strong trend", make(24,1440,3.0,0.4))
run("P=24 + strong trend, NO detrend", make(24,1440,3.0,0.4), force='raw')
run("P=168 clean (long season)", make(168,10080,0.0,0.1))
run("P=24 + weak weekly 0.3", make(24,10080,0.0,0.3,sec=0.3))
run("P=24 + strong weekly 1.0", make(24,10080,0.0,0.3,sec=1.0))
run("P=24 harmonic distortion", make(24,1440,0.0,0.3,harm=0.8))
run("pure noise", [random.Random(7).gauss(0,1) for _ in range(1440)])
run("P=24, 3 seasons only", make(24,72,0.0,0.3))
run("P=24.7 fractional", [math.sin(2*math.pi*i/24.7)+0.4*random.Random(3).gauss(0,1) for i in range(1440)])
run("P=2.4 (near alias limit)", [math.sin(2*math.pi*i/2.4)+0.3*random.Random(4).gauss(0,1) for i in range(1440)])
