import math, random, time
def acf(x,kmax):
    n=len(x); m=sum(x)/n; d=[v-m for v in x]; c0=sum(v*v for v in d)/n or 1e-12
    return [(sum(d[i]*d[i+k] for i in range(n-k))/n)/c0 for k in range(1,kmax+1)]
def maxima(r): return [k for k in range(1,len(r)-1) if r[k]>=r[k-1] and r[k]>r[k+1]]
def prom(r,k):
    left=min(r[0:k+1]); j=k+1
    while j<len(r)-1 and r[j]>=r[j+1]: j+=1
    return r[k]-max(left,r[min(j,len(r)-1)])
def band(r,n):
    s=0.0; b=[]
    for v in r: s+=2*v*v; b.append(1.96*math.sqrt((1+2*s)/n))
    return b
def ma_detrend(x,W=49):
    n=len(x); out=[]
    for i in range(n):
        seg=x[max(0,i-W):min(n,i+W+1)]; out.append(x[i]-sum(seg)/len(seg))
    return out
def trendz(x):
    n=len(x); mx=(n-1)/2; my=sum(x)/n
    sxx=sum((i-mx)**2 for i in range(n)) or 1
    sxy=sum((i-mx)*(x[i]-my) for i in range(n)); b=sxy/sxx
    res=[x[i]-(my-b*mx)-b*i for i in range(n)]
    sr=math.sqrt(sum(e*e for e in res)/max(1,n-2))
    return 0.0 if sr==0 else b/(sr/math.sqrt(sxx))
def sdiff(x,L): return [x[i]-x[i-L] for i in range(L,len(x))]
def make(P,n,trend,noise,sec=0.0,seed=0,harm=0.0):
    rnd=random.Random(seed); out=[]
    for i in range(n):
        v=math.sin(2*math.pi*i/P)+harm*math.sin(4*math.pi*i/P)
        if sec: v+=sec*math.sin(2*math.pi*i/168)
        out.append(v+trend*(i/n)+noise*rnd.gauss(0,1))
    return out

def detect(x, kmax=400):
    n=len(x)
    if n<12 or set(x)=={x[0]}: return None,"degenerate"
    km=min(kmax,max(2,n//3))
