    keep=[]
    for k in sig:                       # reject integer multiples of any smaller significant peak
        if any(k%d==0 and (k//d) in sig and k//d>=2 for d in range(2,k//2+1)): continue
        keep.append(k)
    out=[]
    for k in keep:
        sd=sdiff(use,k)
        if len(sd)>3*k:
            r2=acf(sd,min(k,len(sd)//3)); drop=r[k-1]-r2[k-1]
        else: drop=float('nan')
        out.append((round(drop,3), round(prom(r,k),3), k, round(r[k-1],3)))
    out.sort(reverse=True)
    return out, ("detrended" if use is not x else "raw")

def show(lbl,x,kmax=400):
