def trendz(x):
    n=len(x);mx=(n-1)/2;my=sum(x)/n;sxx=sum((i-mx)**2 for i in range(n)) or 1
    b=sum((i-mx)*(x[i]-my) for i in range(n))/sxx
    res=[x[i]-(my-b*mx)-b*i for i in range(n)];sr=math.sqrt(sum(e*e for e in res)/max(1,n-2))
    return 0.0 if sr==0 else b/(sr/math.sqrt(sxx))
def make(P,n,tr,ns,sec=0.0,seed=0,harm=0.0):
    rnd=random.Random(seed);o=[]
    for i in range(n):
        v=math.sin(2*math.pi*i/P)+harm*math.sin(4*math.pi*i/P)
        if sec: v+=sec*math.sin(2*math.pi*i/168)
        o.append(v+tr*(i/n)+ns*rnd.gauss(0,1))
    return o

def detect(x,kmax=400,parsimony=0.90,min_seasons=4,rounds=3):
    n=len(x)
    if n<12: return None,"degenerate:too_short",{}
    if max(x)-min(x)==0: return None,"degenerate:constant",{}
    km=min(kmax,max(2,n//3))
    rep = ma_dt(x) if abs(trendz(x))>3 else x
    tag = "detrended" if rep is not x else "raw"
    r=acf(rep,km); b=band(r,n)
    peaks=[k for k in range(1,km-1) if r[k]>=r[k-1] and r[k]>r[k+1] and r[k]>b[k] and prom(r[k:] and r,k)>b[k]]
    if not peaks: return [],tag,{"reason":"no significant prominence-gated peak"}
    def near_mult(a,c): return abs(a-c*round(a/c)) <= max(1,0.02*c)
    fam={}
    for k in peaks:
        if any(p<k and near_mult(k,p) for p in peaks): continue   # harmonic of a smaller peak
        tot=0.0
        m=1
        while m*k<=km and m<=rounds:
            idx=round(k*m)
            if idx<km: tot+=max(0.0,r[idx])
            m+=1
        fam[k]=tot/rounds
    if not fam: return [],tag,{"reason":"all peaks explained as harmonics"}
    best=max(fam.values())
    elig=sorted(k for k,v in fam.items() if v>=parsimony*best)      # smallest sufficient fundamental
    L=elig[0]
    sd=[rep[i]-rep[i-L] for i in range(L,len(rep))]
    r2=acf(sd,min(L,max(2,len(sd)//3))) if len(sd)>3*L else None
    drop=(r[L-1]-r2[L-1]) if r2 else None
    conf=min(1.0,best/ (rounds*0.9)) * (1.0 if drop and drop>0.3 else 0.5)
    return elig, tag, {"L":L,"fam_energy":round(best,3),"sd_drop":None if drop is None else round(drop,3),
                       "n_seasons":round(n/L,1),"runner_up":elig[1] if len(elig)>1 else None,
                       "margin":None if len(elig)<2 else round(fam[elig[0]]-fam[elig[1]],3),"conf":round(conf,2)}

