import math, random, time
# ACF indexed by LAG: acf[k] = rho(k), k>=1 ; acf[0] unused
def acf(x,kmax):
    n=len(x);m=sum(x)/n;d=[v-m for v in x];c0=sum(v*v for v in d)/n or 1e-12
    return {k:(sum(d[i]*d[i+k] for i in range(n-k))/n)/c0 for k in range(1,kmax+1)}
def prom(r,k):
    ks=sorted(r); left=min([r[j] for j in range(min(ks),k)]+[r[k]]); j=k+1; ks=sorted(r)
    hi=ks[-1]
    while j<hi and r[j]>=r[j+1]: j+=1
    return r[k]-max(left, r[min(j,hi)])
def band(r,n):
    s=0.0;b={}
    for k in sorted(r): s+=2*r[k]**2; b[k]=1.96*math.sqrt((1+2*s)/n)
    return b
def ma_dt(x,W=49):
    n=len(x);o=[]
    for i in range(n):
        g=x[max(0,i-W):min(n,i+W+1)];o.append(x[i]-sum(g)/len(g))
    return o
def trendz(x):
    n=len(x);mx=(n-1)/2;my=sum(x)/n;sxx=sum((i-mx)**2 for i in range(n)) or 1
    b=sum((i-mx)*(x[i]-my) for i in range(n))/sxx
    res=[x[i]-(my-b*mx)-b*i for i in range(n)];sr=math.sqrt(sum(e*e for e in res)/max(1,n-2))
    return 0.0 if sr==0 else b/(sr/math.sqrt(sxx))
def make(P,n,tr,ns,sec=0.0,seed=0,harm=0.0):
    rnd=random.Random(seed);o=[]
    for i in range(n):
        v=math.sin(2*math.pi*i/P)+harm*math.sin(4*math.pi*i/P)
        if sec: v+=sec*math.sin(2*math.pi*i/168)
        o.append(v+tr*(i/n)+ns*rnd.gauss(0,1))
    return o
def detect(x,kmax=400,parsim=0.90,rounds=3,gate=0.15):
    n=len(x)
    if n<12: return {"abstain":"too_short"}
    if max(x)==min(x): return {"abstain":"constant"}
    km=min(kmax,max(2,n//3))
    use=ma_dt(x) if abs(trendz(x))>3 else x; tag="detrended" if use is not x else "raw"
    r=acf(use,km); b=band(r,n)
    peaks=[k for k in range(2,km-1) if r[k]>=r[k-1] and r[k]>r[k+1] and r[k]>b[k] and prom(r,k)>b[k]]
    warn=["acf_elevated_at_kmax"] if r[km]>b[km] else []
    if not peaks: return {"abstain":"no_prominent_significant_peak","rep":tag,"warn":warn}
    cl=[];cur=[peaks[0]]
    for k in peaks[1:]:
        if k-cur[-1]<=max(1,round(0.02*cur[-1]))+1: cur.append(k)
        else: cl.append(cur);cur=[k]
    cl.append(cur)
    reps=[max(c,key=lambda k:r[k]) for c in cl]
    fam={}
    for k in reps:
        if any(p<k and abs(k-p*round(k/p))<=max(1,round(0.02*p)) for p in reps): continue
        fam[k]=sum(max(0.0,r[min(km,round(k*m))]) for m in range(1,rounds+1))/rounds
    if not fam: return {"abstain":"all_peaks_harmonic","rep":tag,"warn":warn}
    best=max(fam.values())
    if best<gate: return {"abstain":"energy_below_gate","fam":round(best,3),"rep":tag,"warn":warn}
    elig=sorted(k for k,v in fam.items() if v>=parsim*best); L=elig[0]
    sd=[use[i]-use[i-L] for i in range(L,len(use))]; drop=None
    if len(sd)>3*L:
        r2=acf(sd,min(L,max(2,len(sd)//3))); drop=round(r[L]-r2[L],3)
    W=n//5; stab=[]
    for s in range(0,max(1,n-W+1),max(1,W//2)):
        seg=use[s:s+W]
        if len(seg)<4*L: continue
        rs=acf(seg,min(L+max(1,int(0.05*L)),len(seg)//3))
        w=max(rs,key=lambda k:rs[k]); stab.append(abs(w-L)<=max(1,round(0.02*L)))
    return {"L":L,"elig":elig,"fam":round(best,3),"runner":elig[1] if len(elig)>1 else None,
            "margin":round(fam[elig[0]]-fam[elig[1]],3) if len(elig)>1 else None,"sd_drop":drop,
            "stab":round(sum(stab)/len(stab),2) if stab else None,"rep":tag,"nseasons":round(n/L,1),"warn":warn}
def show(l,x,**kw):
    d=detect(x,**kw); print(f"{l:<28} L*={str(d.get('L','ABSTAIN/'+str(d.get('abstain')))):<6} {d}")
