        if len(seg)<4*L: continue
        km=min(max(cands)+5,len(seg)//3); r=acf(seg,km)
        loc=[k for k in cands if 1<k<km-1 and r[k]>=r[k-1] and r[k]>r[k+1]]
        if not loc: continue
        win=max(loc,key=lambda k:fam_energy(r,k,km)) if mode=='fam' else max(loc,key=lambda k:r[k])
        ok+= abs(win-L)<=max(1,round(0.02*L)); tot+=1
    return (round(ok/tot,2) if tot else None), tot
# FIX 2: bootstrap preserving periodicity -- block length = m*L, and circular shift
def circ_shift_stab(x,L,cands,B=20,seed=0):
    rnd=random.Random(seed); n=len(x); ok=0
    for _ in range(B):
        s=rnd.randrange(1,L)  # sub-period phase shift keeps periodicity intact
        y=x[s:]+x[:s]
        km=min(max(cands)+5,n//3); r=acf(y,km)
        loc=[k for k in cands if 1<k<km-1 and r[k]>=r[k-1] and r[k]>r[k+1]]
